/**
 * The operations screens perform. Each one changes local data and queues
 * the same change for the server through `mutate`, so the UI can update
 * immediately and the network can be absent.
 *
 * Ids for locally created words and notebooks are ULIDs minted here. The
 * API accepts client-generated ids on push, so an offline creation keeps
 * the same identity once it reaches the server.
 */
import {
  advanceStreak,
  dayIndex,
  effectiveStreak,
  defaultSettings,
  newProgress,
  pairKey,
  review,
  reviewDay,
  type AnswerCardType,
  type EffectiveSchedule,
  type EnabledCardType,
  type Progress,
  type Settings,
  type Source,
  type Streak,
  type Word,
  type LanguageCode,
  normalizeHeadword,
} from '@lexpad/core';
import type { ApiExample, ApiMeaning, ApiPhrase, ApiReviewEvent } from '@/api/types.js';
import {
  bumpDayStat,
  getWord,
  loadSchedule,
  loadStreak,
  mutate,
  putProgress,
  putStreak,
  writableTables,
} from './repo.js';
import {
  db,
  getMeta,
  setMeta,
  type StoredNotebook,
  type StoredWord,
  type LexpadDb,
  type UndoPayload,
} from './schema.js';
import { newId } from '@/lib/id.js';

/**
 * The fields the add sheet collects. The first sense is spelled out as flat
 * fields because that is what the form edits; a model-written card, or a
 * learner who knows a word has more than one meaning, carries the rest in
 * `extraMeanings` and the lists below. Everything here ends up on the word.
 */
export interface WordDraft {
  headword: string;
  meaning: string;
  gloss?: string;
  example?: string;
  translation?: string;
  /** Further examples of the first sense, beyond the one the form edits. */
  moreExamples?: ApiExample[];
  /** Senses after the first, in the API's shape. */
  extraMeanings?: ApiMeaning[];
  expressions?: ApiPhrase[];
  collocations?: string[];
  relatedWords?: ApiPhrase[];
  usageNote?: string;
  spellingNote?: string;
  /** The natural form of a headword that was typed misspelled or awkwardly. */
  correction?: string;
  pronunciation?: string;
  pos?: string;
  level?: string;
  category?: string;
  memo?: string;
  trickySpelling?: boolean;
  /** Where the entry came from; hand-typed unless a generator says otherwise. */
  source?: Source;
}

/** A blank or missing topic becomes the default, as the server would do. */
function normalizeCategory(value: string | undefined): string {
  const trimmed = value?.trim() ?? '';
  return trimmed === '' ? 'general' : trimmed;
}

/** The CEFR bands, so a free-text level can be validated rather than cast. */
const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'] as const;
type Level = (typeof LEVELS)[number];

function asLevel(value: string | undefined): Level | undefined {
  return LEVELS.find((level) => level === value?.toUpperCase());
}

/**
 * Builds the local row a draft becomes. This is deliberately the stored
 * shape rather than an API request shape: the outbox pushes whole words
 * through `/sync/push`, so the local row is also the wire payload, and the
 * app never constructs a request body deep inside a mutation.
 */
export function draftToWord(
  id: string,
  notebookId: string,
  position: number,
  draft: WordDraft,
  now: Date = new Date(),
): StoredWord {
  const examples: ApiExample[] = [];
  if (draft.example) {
    const example: ApiExample = { sentence: draft.example };
    if (draft.translation) example.translation = draft.translation;
    examples.push(example);
  }
  examples.push(...cleanExamples(draft.moreExamples));
  const meaning: ApiMeaning = { meaning: draft.meaning.trim(), examples };
  if (draft.gloss) meaning.gloss = draft.gloss;

  const timestamp = now.toISOString();
  const stored: StoredWord = {
    id,
    notebookId,
    headword: draft.headword.trim(),
    category: normalizeCategory(draft.category),
    source: draft.source ?? 'manual',
    position,
    createdAt: timestamp,
    updatedAt: timestamp,
    meanings: [...(meaning.meaning === '' ? [] : [meaning]), ...cleanMeanings(draft.extraMeanings)],
    expressions: cleanPhrases(draft.expressions),
    collocations: cleanList(draft.collocations),
    relatedWords: cleanPhrases(draft.relatedWords),
    relatedWordIds: [],
  };
  const level = asLevel(draft.level);
  if (draft.pos) stored.pos = draft.pos.trim();
  if (level) stored.level = level;
  if (draft.pronunciation) stored.pronunciation = draft.pronunciation.trim();
  if (draft.trickySpelling === true) stored.trickySpelling = true;
  if (draft.usageNote?.trim()) stored.usageNote = draft.usageNote.trim();
  if (draft.spellingNote?.trim()) stored.spellingNote = draft.spellingNote.trim();
  if (draft.correction?.trim()) stored.correction = draft.correction.trim();
  return stored;
}

/**
 * The draft a word's screen edits: the inverse of `draftToWord`. The private
 * note is learning state, not part of the word, so it is not here.
 */
export function draftFromWord(word: Word | StoredWord): WordDraft {
  const [first, ...rest] = word.meanings ?? [];
  const [example, ...moreExamples] = first?.examples ?? [];
  const draft: WordDraft = {
    headword: word.headword,
    meaning: first?.meaning ?? '',
    category: word.category,
    source: word.source,
  };
  if (first?.gloss !== undefined) draft.gloss = first.gloss;
  if (example !== undefined) draft.example = example.sentence;
  if (example?.translation !== undefined) draft.translation = example.translation;
  if (moreExamples.length > 0) draft.moreExamples = moreExamples;
  if (rest.length > 0) draft.extraMeanings = rest;
  if ((word.expressions ?? []).length > 0) draft.expressions = word.expressions ?? [];
  if ((word.collocations ?? []).length > 0) draft.collocations = word.collocations ?? [];
  if ((word.relatedWords ?? []).length > 0) draft.relatedWords = word.relatedWords ?? [];
  if (word.usageNote !== undefined) draft.usageNote = word.usageNote;
  if (word.spellingNote !== undefined) draft.spellingNote = word.spellingNote;
  if (word.correction !== undefined) draft.correction = word.correction;
  if (word.pronunciation !== undefined) draft.pronunciation = word.pronunciation;
  if (word.pos !== undefined) draft.pos = word.pos;
  if (word.level !== undefined) draft.level = word.level;
  if (word.trickySpelling !== undefined) draft.trickySpelling = word.trickySpelling;
  return draft;
}

/**
 * Replaces a word's content with an edited draft. Identity, position, origin,
 * links to other notebook words and the learning state are kept; everything
 * the form shows is taken from the draft, so a sense or a collocation the
 * learner removed is gone.
 */
export async function saveWordDraft(
  wordId: string,
  draft: WordDraft,
  database: LexpadDb = db,
): Promise<void> {
  const existing = await database.words.get(wordId);
  if (!existing) return;
  const incoming = draftToWord(existing.id, existing.notebookId, existing.position, draft);
  const updated: StoredWord = {
    ...incoming,
    createdAt: existing.createdAt,
    updatedAt: new Date().toISOString(),
    source: existing.source,
    relatedWordIds: existing.relatedWordIds ?? [],
  };
  if (existing.aiModel !== undefined) updated.aiModel = existing.aiModel;
  if (existing.originalMeaning !== undefined) updated.originalMeaning = existing.originalMeaning;
  if (existing.relatedNote !== undefined) updated.relatedNote = existing.relatedNote;
  await putWordRow(updated, database);
}

/** Writes a whole word row locally and queues it, the way every word edit ends. */
async function putWordRow(updated: StoredWord, database: LexpadDb): Promise<void> {
  await mutate(
    {
      entity: 'word',
      entityId: updated.id,
      op: 'upsert',
      payload: updated,
      async apply(database_) {
        await database_.words.put(updated);
      },
    },
    database,
  );
}

/**
 * Renames a word to the corrected form the model suggested and clears the
 * suggestion. Refuses when the notebook already has that headword, since
 * two entries cannot share one.
 */
export async function applyCorrection(
  wordId: string,
  database: LexpadDb = db,
): Promise<'renamed' | 'taken' | 'nothing'> {
  const existing = await database.words.get(wordId);
  const target = existing?.correction?.trim() ?? '';
  if (!existing || target === '') return 'nothing';
  const key = normalizeHeadword(target);
  const clash = await database.words
    .where('notebookId')
    .equals(existing.notebookId)
    .filter((word) => word.id !== wordId && normalizeHeadword(word.headword) === key)
    .count();
  if (clash > 0) return 'taken';
  const { correction: _correction, ...rest } = existing;
  await putWordRow({ ...rest, headword: target, updatedAt: new Date().toISOString() }, database);
  return 'renamed';
}

/** Drops a suggested correction: the learner's spelling stands. */
export async function dismissCorrection(wordId: string, database: LexpadDb = db): Promise<void> {
  const existing = await database.words.get(wordId);
  if (existing?.correction === undefined) return;
  const { correction: _correction, ...rest } = existing;
  await putWordRow({ ...rest, updatedAt: new Date().toISOString() }, database);
}

/**
 * Moves one of a word's meanings to another place in its list. The first
 * meaning is the one practice asks about, so this is how a learner says which
 * sense they saved the word for. Returns false when there is nothing to move.
 */
export async function moveMeaning(
  wordId: string,
  from: number,
  to: number,
  database: LexpadDb = db,
): Promise<boolean> {
  const existing = await database.words.get(wordId);
  const meanings = existing?.meanings ?? [];
  if (!existing || from === to || from < 0 || to < 0 || from >= meanings.length || to >= meanings.length) {
    return false;
  }
  const next = [...meanings];
  const [moved] = next.splice(from, 1);
  if (moved === undefined) return false;
  next.splice(to, 0, moved);
  await putWordRow({ ...existing, meanings: next, updatedAt: new Date().toISOString() }, database);
  return true;
}

/** Trims senses and drops empty ones and empty examples. */
function cleanMeanings(meanings: ApiMeaning[] | undefined): ApiMeaning[] {
  const out: ApiMeaning[] = [];
  for (const sense of meanings ?? []) {
    const text = sense.meaning.trim();
    if (text === '') continue;
    const clean: ApiMeaning = { meaning: text, examples: cleanExamples(sense.examples) };
    if (sense.gloss?.trim()) clean.gloss = sense.gloss.trim();
    out.push(clean);
  }
  return out;
}

function cleanExamples(examples: ApiExample[] | undefined): ApiExample[] {
  const out: ApiExample[] = [];
  for (const example of examples ?? []) {
    const sentence = example.sentence.trim();
    if (sentence === '') continue;
    const kept: ApiExample = { sentence };
    if (example.translation?.trim()) kept.translation = example.translation.trim();
    out.push(kept);
  }
  return out;
}

function cleanPhrases(phrases: ApiPhrase[] | undefined): ApiPhrase[] {
  const out: ApiPhrase[] = [];
  for (const phrase of phrases ?? []) {
    const text = phrase.text.trim();
    if (text === '') continue;
    const kept: ApiPhrase = { text };
    if (phrase.translation?.trim()) kept.translation = phrase.translation.trim();
    out.push(kept);
  }
  return out;
}

function cleanList(items: string[] | undefined): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const item of items ?? []) {
    const text = item.trim();
    const key = normalizeHeadword(text);
    if (key === '' || seen.has(key)) continue;
    seen.add(key);
    out.push(text);
  }
  return out;
}

/** The position after every word in the notebook, where a new one goes. */
async function nextPosition(database: LexpadDb, notebookId: string): Promise<number> {
  const words = await database.words.where('notebookId').equals(notebookId).toArray();
  return words.reduce((top, word) => Math.max(top, word.position), 0) + 1;
}

/** The notebook's word with this headword, however it is spelled or cased. */
async function findByHeadword(
  database: LexpadDb,
  notebookId: string,
  headword: string,
): Promise<StoredWord | undefined> {
  const key = normalizeHeadword(headword);
  if (key === '') return undefined;
  return database.words
    .where('notebookId')
    .equals(notebookId)
    .filter((word) => normalizeHeadword(word.headword) === key)
    .first();
}

/** Writes a word back with a new place in its notebook. */
async function placeWord(updated: StoredWord, database: LexpadDb): Promise<void> {
  await mutate(
    {
      entity: 'word',
      entityId: updated.id,
      op: 'upsert',
      payload: updated,
      async apply(database_) {
        await database_.words.put(updated);
      },
    },
    database,
  );
}

/** Where a word sat before it was moved, so the move can be undone. */
export interface WordOrder {
  position: number;
  createdAt: string;
}

/**
 * Moves a word to the top of its notebook, as if it had just been added: last
 * position, added now. The server reads the later createdAt the same way.
 * Returns where the word was, or undefined when there is no such word.
 */
export async function raiseWord(wordId: string, database: LexpadDb = db): Promise<WordOrder | undefined> {
  const existing = await database.words.get(wordId);
  if (!existing) return undefined;
  const before: WordOrder = { position: existing.position, createdAt: existing.createdAt };
  const now = new Date().toISOString();
  await placeWord(
    {
      ...existing,
      position: await nextPosition(database, existing.notebookId),
      createdAt: now,
      updatedAt: now,
    },
    database,
  );
  return before;
}

/** Puts a moved word back where it was. */
export async function restoreWordOrder(
  wordId: string,
  order: WordOrder,
  database: LexpadDb = db,
): Promise<void> {
  const existing = await database.words.get(wordId);
  if (!existing) return;
  await placeWord({ ...existing, ...order, updatedAt: new Date().toISOString() }, database);
}

/**
 * Adds a word to a notebook. Returns the id it was given.
 *
 * A headword the notebook already has is not an error: adding it again is a
 * request to see it again, so the existing word moves to the top like a new
 * one, keeps everything it had, and gains the typed meaning if that is new.
 */
export async function addWord(
  notebookId: string,
  draft: WordDraft,
  timeZone: string,
  database: LexpadDb = db,
): Promise<string> {
  const twin = await findByHeadword(database, notebookId, draft.headword);
  if (twin) {
    const meaning = draft.meaning.trim();
    const meanings = twin.meanings ?? [];
    const known = meanings.some((sense) => sense.meaning.trim().toLowerCase() === meaning.toLowerCase());
    const now = new Date().toISOString();
    await placeWord(
      {
        ...twin,
        meanings: meaning === '' || known ? meanings : [...meanings, { meaning }],
        position: await nextPosition(database, notebookId),
        createdAt: now,
        updatedAt: now,
      },
      database,
    );
    if (draft.memo !== undefined && draft.memo.trim() !== '') {
      await setProgressFlags(twin.id, { memo: draft.memo }, timeZone, new Date(), database);
    }
    return twin.id;
  }

  const id = newId();
  const position = await nextPosition(database, notebookId);
  const stored = draftToWord(id, notebookId, position, draft);

  await mutate(
    {
      entity: 'word',
      entityId: id,
      op: 'upsert',
      payload: stored,
      async apply(database_) {
        await database_.words.put(stored);
        const notebook = await database_.notebooks.get(notebookId);
        if (notebook) await database_.notebooks.put({ ...notebook, wordCount: notebook.wordCount + 1 });
      },
    },
    database,
  );
  // A note typed in the add sheet belongs to the learner, not the word, so
  // it is stored as progress and pushed as its own change.
  if (draft.memo !== undefined && draft.memo.trim() !== '') {
    await setProgressFlags(id, { memo: draft.memo }, timeZone, new Date(), database);
  }
  return id;
}

/** Applies a partial edit to a word. */
export async function editWord(
  wordId: string,
  patch: Partial<StoredWord>,
  database: LexpadDb = db,
): Promise<void> {
  const existing = await database.words.get(wordId);
  if (!existing) return;
  const updated: StoredWord = { ...existing, ...patch, updatedAt: new Date().toISOString() };
  await mutate(
    {
      entity: 'word',
      entityId: wordId,
      op: 'upsert',
      payload: updated,
      async apply(database_) {
        await database_.words.put(updated);
      },
    },
    database,
  );
}

/**
 * Pours a model-written card into a word that already exists, adding what
 * the word lacks and never touching what the learner already has: senses,
 * expressions, collocations and related words are added when their text is
 * new; part of speech, level, pronunciation and the notes are filled only
 * when empty. The headword, the correction, the private note and the
 * learning state stay as they are. Returns how many items were added.
 */
export async function enrichWord(wordId: string, card: WordDraft, database: LexpadDb = db): Promise<number> {
  const existing = await database.words.get(wordId);
  if (!existing) return 0;
  const incoming = draftToWord(existing.id, existing.notebookId, existing.position, {
    ...card,
    headword: existing.headword,
  });
  const patch: Partial<StoredWord> = {};
  let added = 0;

  const meanings = [...(existing.meanings ?? [])];
  // A word that already has two or more senses is not thin; what the model
  // adds to it is mostly the same senses in other words. Senses are only
  // added to a word that has at most one.
  if (meanings.length <= 1) {
    for (const sense of incoming.meanings ?? []) {
      if (meanings.some((known) => sameSense(known, sense))) continue;
      meanings.push(sense);
      added++;
    }
  }
  // A sense the learner already had may have been written without an
  // example; the model's example for the same sense is worth keeping.
  for (const sense of meanings) {
    if ((sense.examples ?? []).length > 0) continue;
    const match = (incoming.meanings ?? []).find((candidate) => sameSense(sense, candidate));
    const borrowed = match?.examples ?? [];
    if (borrowed.length > 0) {
      sense.examples = borrowed;
      added++;
    }
  }
  if (added > 0) patch.meanings = meanings;

  const mergePhrases = (
    have: ApiPhrase[] | undefined,
    more: ApiPhrase[] | undefined,
  ): ApiPhrase[] | undefined => {
    const out = [...(have ?? [])];
    const known = new Set(out.map((phrase) => normalizeHeadword(phrase.text)));
    let grew = false;
    for (const phrase of more ?? []) {
      if (known.has(normalizeHeadword(phrase.text))) continue;
      known.add(normalizeHeadword(phrase.text));
      out.push(phrase);
      added++;
      grew = true;
    }
    return grew ? out : undefined;
  };
  const expressions = mergePhrases(existing.expressions, incoming.expressions);
  if (expressions) patch.expressions = expressions;
  const relatedWords = mergePhrases(existing.relatedWords, incoming.relatedWords);
  if (relatedWords) patch.relatedWords = relatedWords;
  const collocations = cleanList([...(existing.collocations ?? []), ...(incoming.collocations ?? [])]);
  if (collocations.length > (existing.collocations ?? []).length) {
    added += collocations.length - (existing.collocations ?? []).length;
    patch.collocations = collocations;
  }

  if (!existing.pos && incoming.pos !== undefined) {
    patch.pos = incoming.pos;
    added++;
  }
  if (!existing.level && incoming.level !== undefined) {
    patch.level = incoming.level;
    added++;
  }
  if (!existing.pronunciation && incoming.pronunciation !== undefined) {
    patch.pronunciation = incoming.pronunciation;
    added++;
  }
  if (
    !existing.usageNote &&
    incoming.usageNote !== undefined &&
    senseKey(incoming.usageNote) !== senseKey(existing.headword)
  ) {
    patch.usageNote = incoming.usageNote;
    added++;
  }
  if (!existing.spellingNote && incoming.spellingNote !== undefined) {
    patch.spellingNote = incoming.spellingNote;
    added++;
  }
  if (incoming.trickySpelling === true && existing.trickySpelling !== true) {
    patch.trickySpelling = true;
    added++;
  }

  if (added === 0) return 0;
  await editWord(wordId, patch, database);
  return added;
}

/**
 * Whether two senses say the same thing. The model rewords: "بلندپرواز" and
 * "بلندپرواز، دارای آرزوهای بزرگ" are one sense, as are two senses with the
 * same gloss. One meaning that begins with the other, whole words only, or
 * matching glosses, counts as the same. Plain containment would not do:
 * "تعلیق" (a ban) and "سیستم تعلیق خودرو" (a car's springs) are two senses.
 */
function sameSense(a: ApiMeaning, b: ApiMeaning): boolean {
  const left = senseKey(a.meaning);
  const right = senseKey(b.meaning);
  if (left === '' || right === '') return left === right;
  if (left === right || left.startsWith(`${right} `) || right.startsWith(`${left} `)) return true;
  const glossA = senseKey(a.gloss ?? '');
  const glossB = senseKey(b.gloss ?? '');
  return glossA !== '' && glossA === glossB;
}

/** Sense text as words only: case- and accent-folded, punctuation dropped. */
function senseKey(text: string): string {
  return normalizeHeadword(text)
    .replace(/[\p{P}\p{S}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Removes a word from the notebook. */
export async function removeWord(wordId: string, database: LexpadDb = db): Promise<void> {
  const existing = await database.words.get(wordId);
  await mutate(
    {
      entity: 'word',
      entityId: wordId,
      op: 'delete',
      async apply(database_) {
        await database_.words.delete(wordId);
        await database_.progress.delete(wordId);
        if (existing) {
          const notebook = await database_.notebooks.get(existing.notebookId);
          if (notebook) {
            await database_.notebooks.put({ ...notebook, wordCount: Math.max(0, notebook.wordCount - 1) });
          }
        }
      },
    },
    database,
  );
}

/** Creates a notebook locally. Returns the id it was given. */
export async function addNotebook(
  input: { title: string; targetLang: LanguageCode; meaningLang: LanguageCode; isDefault?: boolean },
  database: LexpadDb = db,
): Promise<string> {
  const id = newId();
  const now = new Date().toISOString();
  const count = await database.notebooks.count();
  const notebook: StoredNotebook = {
    id,
    title: input.title.trim(),
    targetLang: input.targetLang,
    meaningLang: input.meaningLang,
    isDefault: input.isDefault ?? count === 0,
    sortOrder: count,
    role: 'owner',
    wordCount: 0,
    createdAt: now,
    updatedAt: now,
  };
  await mutate(
    {
      entity: 'notebook',
      entityId: id,
      op: 'upsert',
      payload: notebook,
      async apply(database_) {
        if (notebook.isDefault) {
          const others = await database_.notebooks.toArray();
          await Promise.all(
            others
              .filter((other) => other.isDefault)
              .map((other) => database_.notebooks.put({ ...other, isDefault: false })),
          );
        }
        await database_.notebooks.put(notebook);
      },
    },
    database,
  );
  return id;
}

/**
 * Edits a notebook: its title or the pair of languages. Changing a language
 * changes text direction, fonts and the speech voice everywhere, which is why
 * it is a notebook property rather than a setting.
 */
export async function updateNotebook(
  notebookId: string,
  patch: { title?: string; targetLang?: LanguageCode; meaningLang?: LanguageCode; isDefault?: boolean },
  database: LexpadDb = db,
): Promise<void> {
  const existing = await database.notebooks.get(notebookId);
  if (!existing) return;
  const next: StoredNotebook = {
    ...existing,
    ...(patch.title === undefined ? {} : { title: patch.title.trim() }),
    ...(patch.targetLang === undefined ? {} : { targetLang: patch.targetLang }),
    ...(patch.meaningLang === undefined ? {} : { meaningLang: patch.meaningLang }),
    ...(patch.isDefault === undefined ? {} : { isDefault: patch.isDefault }),
    updatedAt: new Date().toISOString(),
  };
  await mutate(
    {
      entity: 'notebook',
      entityId: notebookId,
      op: 'upsert',
      payload: next,
      async apply(database_) {
        // One default, always. Clearing the others happens inside the
        // transaction rather than in the screen, because a screen computes
        // from a snapshot and two taps can race it into a second default.
        if (next.isDefault) {
          const others = await database_.notebooks.toArray();
          await Promise.all(
            others
              .filter((other) => other.id !== notebookId && other.isDefault)
              .map((other) => database_.notebooks.put({ ...other, isDefault: false })),
          );
        }
        await database_.notebooks.put(next);
      },
    },
    database,
  );
}

/**
 * Deletes a notebook and everything in it.
 *
 * The server soft-deletes the words with it, so one delete is all that goes
 * to the queue; locally they have to go too, or the next render would draw
 * words whose notebook is gone. It refuses to remove the last notebook: the
 * app has nowhere to stand without one, and the gate would send the learner
 * back to onboarding.
 */
export async function removeNotebook(notebookId: string, database: LexpadDb = db): Promise<boolean> {
  const all = await database.notebooks.toArray();
  const going = all.find((notebook) => notebook.id === notebookId);
  if (!going || all.length < 2) return false;

  await mutate(
    {
      entity: 'notebook',
      entityId: notebookId,
      op: 'delete',
      async apply(database_) {
        const words = await database_.words.where('notebookId').equals(notebookId).toArray();
        await database_.progress.bulkDelete(words.map((word) => word.id));
        await database_.words.bulkDelete(words.map((word) => word.id));
        await database_.notebooks.delete(notebookId);
        // The one it was showing has gone, so the app falls back to the
        // default rather than to a notebook that no longer exists.
        if ((await getMeta('activeNotebook', database_)) === notebookId) {
          await setMeta('activeNotebook', null, database_);
        }
        // Something must be the default: it is where a word goes when
        // every notebook is in view, and where the app falls back when the
        // one it was showing has gone.
        const rest = all.filter((notebook) => notebook.id !== notebookId);
        if (!rest.some((notebook) => notebook.isDefault)) {
          const next = rest[0];
          if (next) await database_.notebooks.put({ ...next, isDefault: true });
        }
      },
    },
    database,
  );
  return true;
}

/** One entry of an imported file, already mapped to the local shape. */
export interface ImportRow {
  /** The id the source file used, so its relations can be remapped. */
  ref: string;
  word: Omit<StoredWord, 'id' | 'notebookId' | 'position' | 'createdAt' | 'updatedAt'>;
  relatedRefs: string[];
  /** Learning state carried by a Lexpad export; absent for other files. */
  progress?: Progress;
  /** When the word was first added, from a Lexpad export, so the order survives the move. */
  createdAt?: string;
  /** Its place in the notebook's pages, from a Lexpad export. */
  position?: number;
}

/**
 * Adds a whole file to a notebook.
 *
 * A file can hold a couple of thousand entries, so this does not call
 * `addWord` per row: it writes every word, its fresh learning state and one
 * outbox entry per word inside a single transaction. The result is what
 * adding them by hand would have produced, and a half-written import cannot
 * be left behind if the tab is closed.
 */
export async function importWords(
  notebookId: string,
  rows: readonly ImportRow[],
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<number> {
  if (rows.length === 0) return 0;

  const timestamp = now.toISOString();
  const today = dayIndex(now, timeZone);
  const baseCursor = await getMeta('cursor', database);

  // A Lexpad export names each word's place; keeping that order, and the
  // day each word was added, is what makes the notebook look the same on
  // the other side. Other files are taken in the order they list words.
  const ordered = rows.every((row) => row.position !== undefined)
    ? [...rows].sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
    : rows;
  // Ids are minted first so relations within the file can point at them.
  const ids = new Map(ordered.map((row) => [row.ref, newId()]));
  const words: StoredWord[] = ordered.map((row, index) => ({
    ...row.word,
    id: ids.get(row.ref) ?? newId(),
    notebookId,
    // Placed after the notebook's last word inside the transaction below.
    position: index + 1,
    createdAt: validIso(row.createdAt) ?? timestamp,
    updatedAt: timestamp,
    // Only relations that landed in this same import can be resolved.
    relatedWordIds: row.relatedRefs.map((ref) => ids.get(ref)).filter((id): id is string => id !== undefined),
  }));

  // A Lexpad export carries each word's learning state; it is restored as
  // it was, stamped now. Every other file starts its words fresh.
  const fresh = newProgress(today, now);
  const states = words.map((word, index) => {
    const carried = ordered[index]?.progress;
    const restored = carried === undefined ? undefined : { ...carried, updatedAt: timestamp };
    return { wordId: word.id, progress: restored ?? fresh, restored: restored !== undefined };
  });

  // Links between words go to the server in a second pass. The queue is
  // pushed in order, and a word may point at one still behind it; the
  // server keeps such a word but has to leave the link out. Once every word
  // is there, an update carrying the links, stamped a second later so it
  // reads as the newer edit, puts them back.
  const linked = words.filter((word) => (word.relatedWordIds ?? []).length > 0);
  const linkTimestamp = new Date(now.getTime() + 1000).toISOString();

  await database.transaction('rw', writableTables(database), async () => {
    // After the highest position, read here: the last word by id is not the
    // last in the order once a word has been raised to the top, and a
    // position read before the transaction can be taken by an add meanwhile.
    const from = (await nextPosition(database, notebookId)) - 1;
    for (const word of words) word.position += from;
    await database.words.bulkPut(words);
    await database.progress.bulkPut(states.map((state) => ({ wordId: state.wordId, ...state.progress })));
    await database.outbox.bulkAdd([
      ...words.map((word) => ({
        clientId: newId(),
        entity: 'word' as const,
        entityId: word.id,
        op: 'upsert' as const,
        payload: { ...word, relatedWordIds: [] },
        clientTs: timestamp,
        attempts: 0,
        baseCursor,
      })),
      ...linked.map((word) => ({
        clientId: newId(),
        entity: 'word' as const,
        entityId: word.id,
        op: 'upsert' as const,
        payload: { ...word, updatedAt: linkTimestamp },
        clientTs: linkTimestamp,
        attempts: 0,
        baseCursor,
      })),
      // The server merges progress against the base the client saw; for a
      // word that did not exist there, that base is a fresh start.
      ...states
        .filter((state) => state.restored)
        .map((state) => ({
          clientId: newId(),
          entity: 'progress' as const,
          entityId: state.wordId,
          op: 'upsert' as const,
          payload: { wordId: state.wordId, ...state.progress, base: fresh, srs: 2 },
          clientTs: timestamp,
          attempts: 0,
          baseCursor,
        })),
    ]);
  });

  return words.length;
}

/** An ISO timestamp in canonical UTC form, or undefined when it does not parse. */
function validIso(value: string | undefined): string | undefined {
  if (value === undefined) return undefined;
  const ms = Date.parse(value);
  return Number.isNaN(ms) ? undefined : new Date(ms).toISOString();
}

/** The result of grading one card. */
export interface GradeResult {
  progress: Progress;
  mastered: boolean;
  streakBefore: number;
  streakAfter: number;
  /**
   * The state the grade replaced, read inside the same transaction. Undo
   * puts exactly this back, so undoing the second try of a missed card
   * returns to the state after the first try, not before it.
   */
  before: Progress;
  /** Whether the word had never been answered before this grade. */
  isNew: boolean;
  /** The review's client id, which an undo names to the server. */
  reviewClientId: string;
  /** Whether the grade was right, for the day's totals on undo. */
  correct: boolean;
  /**
   * False when the answer was saved as practice only: a right answer to a
   * word that was not due yet, with the notebook keeping extra practice out
   * of the schedule. The word's box and next check did not move.
   */
  scheduleChanged: boolean;
  /** This answer's miss brought the word to the notebook's leech threshold. */
  leech: boolean;
}

/** Where an answer was given (the API's ReviewEvent.source). */
export type AnswerSource = 'session' | 'selftest' | 'game';

/** What the session knows about the card it just graded. */
export interface GradeInput {
  wordId: string;
  correct: boolean;
  /** A plan's card type, or a practice mode's (which exist only as answers). */
  cardType: AnswerCardType;
  /** The option the learner picked when it was wrong, for confusion pairs. */
  pickedWordId?: string;
  typed?: string;
  /** From the card being shown to the answer, in milliseconds. */
  latencyMs?: number;
  /** One id per session run (a UUID). */
  sessionId?: string;
  source?: AnswerSource;
  /** The deck the session drew from. */
  deck?: string;
  /** The in-session second try of a missed card. */
  requeued?: boolean;
  /**
   * The schedule of the word's notebook, read once when a session starts.
   * Without it the grade reads it from the word's notebook. The server
   * computes the same and is the judge; this copy is what the screen shows
   * at once.
   */
  schedule?: EffectiveSchedule;
}

/**
 * Grades a card: applies the schedule, records the spelling miss, updates
 * the day's totals and the streak, notes a confusion pair, and queues the
 * review event for the server with everything SRS v2 logs.
 */
export async function gradeCard(
  input: GradeInput,
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<GradeResult> {
  const today = dayIndex(now, timeZone);
  const reviewClientId = newId();
  // Everything this grade is built on is read inside the transaction. Two
  // grades in quick succession would otherwise both start from the state
  // before either landed, and the second would quietly undo the first: the
  // box, the counters and the streak would each lose an update.
  let isNew = true;
  let before: Progress = newProgress(today, now);
  let after: Progress = before;
  let mastered = false;
  let scheduleChanged = true;
  let leech = false;
  let streakBefore: Streak = { current: 0, longest: 0 };
  let streakAfter: Streak = streakBefore;

  await mutate(
    {
      entity: 'review',
      entityId: input.wordId,
      op: 'upsert',
      async apply(database_) {
        const existing = await database_.progress.get(input.wordId);
        isNew = existing === undefined;
        if (existing !== undefined) {
          const { wordId: _id, ...rest } = existing;
          before = rest;
        }
        let schedule = input.schedule;
        if (schedule === undefined) {
          const word = await database_.words.get(input.wordId);
          schedule = await loadSchedule(word?.notebookId ?? '', database_);
        }
        const day = reviewDay(now, now, timeZone, before.lastDay);
        const outcome = review(
          before,
          { correct: input.correct, cardType: input.cardType, reviewDay: day, key: input.wordId },
          schedule,
        );
        after = { ...outcome.next, updatedAt: now.toISOString() };
        mastered = outcome.mastered;
        scheduleChanged = outcome.scheduleChanged;
        leech = outcome.leech;
        streakBefore = await loadStreak(database_);
        streakAfter = advanceStreak(streakBefore, today);

        await putProgress(input.wordId, after, database_);
        await bumpDayStat(
          today,
          { reviewed: 1, correct: input.correct ? 1 : 0, newWords: isNew ? 1 : 0 },
          database_,
        );
        await putStreak(streakAfter, database_);
        if (!input.correct && input.pickedWordId !== undefined && input.pickedWordId !== input.wordId) {
          const key = pairKey(input.wordId, input.pickedWordId);
          const [a, b] = key.split('-');
          const row = await database_.confusions.get(key);
          await database_.confusions.put({
            key,
            wordA: a ?? input.wordId,
            wordB: b ?? input.pickedWordId,
            count: (row?.count ?? 0) + 1,
          });
        }
      },
      buildPayload: (): Promise<ApiReviewEvent> =>
        Promise.resolve({
          clientId: reviewClientId,
          wordId: input.wordId,
          cardType: input.cardType,
          correct: input.correct,
          clientTs: now.toISOString(),
          srs: 2,
          tz: timeZone,
          clientDay: today,
          ...(input.source === undefined ? {} : { source: input.source }),
          ...(input.deck === undefined ? {} : { deck: input.deck.slice(0, 32) }),
          ...(input.requeued === undefined ? {} : { requeued: input.requeued }),
          ...(input.pickedWordId ? { pickedWordId: input.pickedWordId } : {}),
          ...(input.typed ? { typed: input.typed } : {}),
          ...(input.latencyMs === undefined ? {} : { latencyMs: Math.max(0, Math.round(input.latencyMs)) }),
          ...(input.sessionId ? { sessionId: input.sessionId } : {}),
          ...(isNew ? {} : { seenUpdatedAt: before.updatedAt }),
        }),
    },
    database,
  );

  return {
    progress: after,
    mastered,
    streakBefore: effectiveStreak(streakBefore, today),
    streakAfter: effectiveStreak(streakAfter, today),
    before,
    isNew,
    reviewClientId,
    correct: input.correct,
    scheduleChanged,
    leech,
  };
}

/** Stars, unstars, retires, brings back or annotates a word. */
export async function setProgressFlags(
  wordId: string,
  change: { starred?: boolean; retired?: boolean; memo?: string },
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<Progress> {
  const today = dayIndex(now, timeZone);
  // Built on what is stored at the moment of writing, like a grade: a star
  // and a retire tapped in quick succession must both survive.
  let base: Progress = newProgress(today, now);
  let next: Progress = base;

  await mutate(
    {
      entity: 'progress',
      entityId: wordId,
      op: 'upsert',
      async apply(database_) {
        const existing = await database_.progress.get(wordId);
        if (existing !== undefined) {
          const { wordId: _id, ...rest } = existing;
          base = rest;
        }
        next = {
          ...base,
          ...(change.starred === undefined ? {} : { starred: change.starred }),
          ...(change.retired === undefined ? {} : { retired: change.retired }),
          updatedAt: now.toISOString(),
        };
        if (change.memo !== undefined) {
          const memo = change.memo.trim();
          if (memo === '') delete next.memo;
          else next.memo = memo;
        }
        await putProgress(wordId, next, database_);
      },
      // srs 2: the server takes the flags from this and the schedule from
      // the answers, never from a pushed box.
      buildPayload: () => Promise.resolve({ wordId, ...next, base, srs: 2 }),
    },
    database,
  );
  return next;
}

/**
 * Takes back a grade (spec §2.11). The word gets exactly the state the grade
 * replaced. If the review is still waiting in the queue and was never sent,
 * it is simply dropped and the server never hears of it; otherwise an `undo`
 * naming the review is queued, which the server answers by restoring the
 * same state. A review whose send was tried may have arrived, so it is
 * dropped and the server is told as well; an undo for a review the server
 * never received only makes sure it is never applied.
 */
export async function undoGrade(
  wordId: string,
  graded: Pick<GradeResult, 'before' | 'reviewClientId' | 'correct'> & Partial<Pick<GradeResult, 'isNew'>>,
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<Progress> {
  const today = dayIndex(now, timeZone);
  const restored: Progress = graded.before;
  await database.transaction('rw', writableTables(database), async () => {
    const queued = await database.outbox
      .where('[entity+entityId]')
      .equals(['review', wordId])
      .filter((item) => (item.payload as ApiReviewEvent | undefined)?.clientId === graded.reviewClientId)
      .first();
    if (queued?.seq !== undefined) await database.outbox.delete(queued.seq);
    if (queued === undefined || queued.attempted === true) {
      const payload: UndoPayload = {
        reviewClientId: graded.reviewClientId,
        clientTs: now.toISOString(),
        restoredUpdatedAt: restored.updatedAt,
      };
      await database.outbox.add({
        clientId: newId(),
        entity: 'undo',
        entityId: wordId,
        op: 'upsert',
        payload,
        clientTs: now.toISOString(),
        baseCursor: await getMeta('cursor', database),
        attempts: 0,
      });
    }
    await putProgress(wordId, restored, database);
    // An undone first answer gives the day its new word back, or the
    // per-day new-word limit would count a word that was taken back.
    await bumpDayStat(
      today,
      { reviewed: -1, correct: graded.correct ? -1 : 0, newWords: graded.isNew === true ? -1 : 0 },
      database,
    );
  });
  return restored;
}

/** Replaces the user's settings. */
export async function saveSettings(settings: Settings, database: LexpadDb = db): Promise<Settings> {
  return patchSettings(settings, database);
}

/**
 * Changes some settings and leaves the rest alone.
 *
 * The merge happens inside the transaction, against what is stored rather
 * than against whatever the caller last saw. Two switches flipped in quick
 * succession would otherwise race: the second would be built on a snapshot
 * taken before the first landed, and would quietly undo it.
 */
export async function patchSettings(patch: Partial<Settings>, database: LexpadDb = db): Promise<Settings> {
  let next: Settings = { ...defaultSettings(), ...patch };
  await mutate(
    {
      entity: 'settings',
      entityId: 'me',
      op: 'upsert',
      async apply(database_) {
        const stored = await getMeta('settings', database_);
        next = {
          ...(stored ?? defaultSettings()),
          ...patch,
          updatedAt: new Date().toISOString(),
        };
        await database_.meta.put({ key: 'settings', value: next });
      },
      buildPayload: () => Promise.resolve(next),
    },
    database,
  );
  return next;
}

/**
 * Switches one card type on or off.
 *
 * The new list is derived from what is stored, not from what the caller
 * last saw, so switching several off in quick succession keeps every
 * change. The last enabled type cannot be switched off: a session with no
 * card type could not be built.
 */
export async function toggleCardType(type: EnabledCardType, database: LexpadDb = db): Promise<Settings> {
  let next: Settings = defaultSettings();
  await mutate(
    {
      entity: 'settings',
      entityId: 'me',
      op: 'upsert',
      async apply(database_) {
        const stored = (await getMeta('settings', database_)) ?? defaultSettings();
        const on = stored.cardTypes.includes(type);
        const cardTypes =
          on && stored.cardTypes.length === 1
            ? stored.cardTypes
            : on
              ? stored.cardTypes.filter((other) => other !== type)
              : [...stored.cardTypes, type];
        next = { ...stored, cardTypes, updatedAt: new Date().toISOString() };
        await database_.meta.put({ key: 'settings', value: next });
      },
      buildPayload: () => Promise.resolve(next),
    },
    database,
  );
  return next;
}

/**
 * Turns the daily reminder on at a time, or off.
 *
 * Off means the two keys are absent rather than set to undefined, which a
 * merge cannot express, so this reads and rewrites inside the transaction
 * like the other settings writers.
 */
export async function setReminder(
  time: string | null,
  timeZone: string,
  database: LexpadDb = db,
): Promise<Settings> {
  let next: Settings = defaultSettings();
  await mutate(
    {
      entity: 'settings',
      entityId: 'me',
      op: 'upsert',
      async apply(database_) {
        const stored = (await getMeta('settings', database_)) ?? defaultSettings();
        const { reminderTime: _time, reminderTz: _zone, ...rest } = stored;
        next = {
          ...rest,
          ...(time === null ? {} : { reminderTime: time, reminderTz: timeZone }),
          updatedAt: new Date().toISOString(),
        };
        await database_.meta.put({ key: 'settings', value: next });
      },
      buildPayload: () => Promise.resolve(next),
    },
    database,
  );
  return next;
}

/**
 * Puts every word back where it started: box 1, nothing reviewed, due today.
 * Stars, retirements and notes are kept; they are the user's, not the
 * schedule's. One transaction and one queued change per word, so the server
 * hears about all of it. (The server merges counters additively, so reps and
 * correct keep their history there; the schedule itself does reset.)
 */
export async function resetProgress(
  timeZone: string,
  now: Date = new Date(),
  database: LexpadDb = db,
): Promise<number> {
  const today = dayIndex(now, timeZone);
  const rows = await database.progress.toArray();
  if (rows.length === 0) return 0;
  const timestamp = now.toISOString();
  const baseCursor = await getMeta('cursor', database);
  const reset = rows.map((row) => ({
    ...newProgress(today, now),
    wordId: row.wordId,
    starred: row.starred,
    retired: row.retired,
    ...(row.memo === undefined ? {} : { memo: row.memo }),
  }));
  await database.transaction('rw', writableTables(database), async () => {
    await database.progress.bulkPut(reset);
    await database.outbox.bulkAdd(
      reset.map(({ wordId, ...progress }) => ({
        clientId: newId(),
        entity: 'progress' as const,
        entityId: wordId,
        op: 'upsert' as const,
        // A v2 reset: the server starts the schedule and the memory state
        // over and keeps its counters, rather than merging a box 1 push.
        payload: { wordId, ...progress, srs: 2, reset: true },
        clientTs: timestamp,
        attempts: 0,
        baseCursor,
      })),
    );
  });
  return reset.length;
}

/** Reads a word for the session, so callers do not import two modules. */
export const readWord = getWord;

/** Re-exported so screens can type a word without reaching into core. */
export type { Word };
